import math
fn putd(mut o &u8,p int,x f64){bits:=u64(math.bits_from_f64(x));for k in 0..8{unsafe{o[p+k]=u8(bits&255)};bits>>=8}}
@[export:'ordinary_least_squares_regressor']
pub fn ordinary_least_squares_regressor(v &i64,n usize,o &u8,cap usize)i64{if isnil(v)||n<6{return -1};nr:=unsafe{v[0]};f:=unsafe{v[1]};t:=unsafe{v[2]};if nr<2||nr>8||f!=2||t<1||t>3||n!=usize(3+nr*3+t*2){return -1};mut g:=[3][3]f64{};mut b:=[3]f64{};mut p:=3;for _ in 0..int(nr){x:=unsafe{v[p]};y:=unsafe{v[p+1]};z:=unsafe{v[p+2]};p+=3;if x < -100||x>100||y < -100||y>100||z < -1000||z>1000{return -1};row:=[3]f64{f64(x),f64(y),1};for i in 0..3{b[i]+=row[i]*f64(z);for j in 0..3{g[i][j]+=row[i]*row[j]}}};for c in 0..3{mut q:=c;for r in c+1..3{if math.abs(g[r][c])>math.abs(g[q][c]){q=r}};if math.abs(g[q][c])<1e-12{return -1};for j in 0..3{tmp:=g[c][j];g[c][j]=g[q][j];g[q][j]=tmp};tmp:=b[c];b[c]=b[q];b[q]=tmp;s:=g[c][c];for j in c..3{g[c][j]/=s};b[c]/=s;for r in 0..3{if r!=c{k:=g[r][c];for j in c..3{g[r][j]-=k*g[c][j]};b[r]-=k*b[c]}}};if cap<int(t)*8||isnil(o){return -2};for r in 0..int(t){x:=unsafe{v[p]};y:=unsafe{v[p+1]};p+=2;if x < -100||x>100||y < -100||y>100{return -1};putd(mut o,r*8,f64(x)*b[0]+f64(y)*b[1]+b[2])};t*8}
